from collections import defaultdict
import math

def min_cost_to_connect_points(n, points):
    colors = defaultdict(set)
    for i in range(n):
        p, color = points[i][0], points[i][1]
        colors[color].add(p)

    red_points, green_points = [color for color, points in colors.items() if color == 'R' or color == 'G'], []
    blue_points = [color for color, points in colors.items() if color == 'B']

    def is_connected(n):
        for i in range(n):
            visited = defaultdict(bool)
            yield from _is_connected(1, i, visited)

    def _is_connected(start, end, visited):
        if start == end:
            yield start
        if visited[start]:
            yield from _is_connected(start, end, visited)
        if start < end and (start in blue_points or end in blue_points):
            yield from _is_connected(start, max(start, end), visited)
        if end < start and (end in blue_points or start in blue_points):
            yield from _is_connected(max(start, end), end, visited)
        for point in [start-1, start+1]:
            if 0 < point <= n and not visited[point]:
                visited[point] = True
                yield from _is_connected(point, end, visited)

    for points in is_connected(len(green_points)), is_connected(len(red_points)):
        cost = 0
        for i in range(len(points)):
            cost += max(0, points[-1] - points[i] - 1)
        yield cost
