def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def find_set_requirements(steps):
    max_steps = 0
    mid = 0
    while True:
        bits = bits_needed(steps, mid)
        if bits >= steps + 1:
            break
        max_steps += 1
        mid += bits_needed(2**max_steps, max_steps)
    return min(mid, max(mid - steps + 1, 1)), max(mid, max_steps)

def bits_needed(a, n):
    return bin(a & (((1 << n) - 1) * (2 ** n >> n)).bit_count())

def answer(n, b, q):
    steps = (b + (n - 1)) // n
    (min_mid, max_mid), (min_steps, max_steps) = find_set_requirements(steps)

    remaining = max_mid - b
    if b - min_mid > remaining:
        return "unfair"
    if min_steps >= remaining:
        return "fair"
    mid = b - (min_steps - remaining)

    if mid < max_mid:
        return "unfair"
    return "fair"

