import sys
from heapq import heappop, heappush

def min_cost_to_connect_preset(cost, rainbow_set):
    n = len(cost)
    colors = set([c for p, c in cost if c not in ['G', 'B']])
    points = [p for p, c in cost if c in ['G', 'B']]
    colors_count = {color: points.count(color) for color in colors}
    total_distance = sum(abs(pp - bb) for pp, _ in cost for bb, _ in cost)

    def find(parent, i):
        if parent[i] != i:
            parent[i] = find(parent, parent[i])
        return parent[i]

    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    def smallest():
        smallest = sys.maxsize
        for p, _ in cost:
            # Filter out valid points that defy Roy and Biv's view
            if not [(p - p0) * rank[p0] for ranking, p0 in rainbow_set if find(parent, p0) == p]:
                smallest = min(smallest, abs(p - pp) * rank[pp])
        return smallest

    rainbow_ranks = [(rank[point], point) for point, rank in colors_count.items()] + sorted([(0, 'G'), (0, 'B')], key=lambda x: x[1])
    rainbow_points = [color for rank, color in rainbow_ranks if color in colors] + ['G', 'B']
    parent = [-1] * n
    rank = [0] * n

    for x, y in cost:
        if x > y:
            x, y = y, x
        if not union(parent, rank, x, y):
            return -1
    for rank, pp in rainbow_ranks:
        if find(parent, pp):
            rainbow_set.append((rank, pp))

    if not union(parent, rank, *rainbow_set[0][1]):
        return -1
    min_cost = smallest()
    for rank, point in rainbow_set[1:]:
        if find(parent, point):
            union(parent, rank, *rainbow_set[0][1])
        current_cost = total_distance - sum(
            (pp - bb) * rank[pp] for pp, rank in rainbow_ranks if not union(parent, rank, *rainbow_set[0]))
        if current_cost < min_cost:
            min_cost = current_cost
    return min_cost + smallest()

