        greens_to_blue = {x: rank[x] for x, c in points if c == 'G'}
    if 'G' in [c for x, c in points] and not ('R' in [c for x, c in points] or 'B' in [c for x, c in points]):
        green_to_bls = rank.copy()
    else:
        green_to_bls = {x: rank[x] for x, c in points if c == 'G'}

    total_cost = sum(point[0] for point in points)
    edges = 0
    for point, color in points:
        if color == 'R':
            edges += point
            total_cost -= point
        if color != 'R':
            gc = (edge for i in red_to_greens.items() for edge in i if find(edge[0], parent) != find(edge[1], parent))
            gb = (edge for i in greens_to_blue.items() for edge in i if find(edge[0], parent) != find(edge[1], parent))
            gbt = (edge for i in green_to_bls.items() for edge in i if find(edge[0], parent) != find(edge[1], parent))
            min_cost = min(point for edge in gb if edge[0] < point and edge[1] > point or edge[0] > point and edge[1] < point)
            if not edges:
                edges, cost = sum(point for edge in gc if edge[0] < point > edge[1]), min_cost
            else:
                edges -= point - min_cost
                total_cost -= point - min_cost
        if not edges:
            break
    return total_cost - edges

