# Function to perform modulo operation
def modpow(x, y, p):
    result = 1
    x = x % p
    while y > 0:
        if y % 2 == 1:
            result = (result * x) % p
        y = y >> 1
        x = (x * x) % p
    return result

# Function to maximize bitwise XOR of two disjoint substrings
def max_xor_substrings(N, S):
    result = 0
    for i in range(N):
        for j in range(i + 2, N + 1):
            sub1 = bin(S[i:j]).count('1')
            sub2 = bin(S[i-1]+S[:i]).count('1')
            sub3 = bin(S[j-1]+S[j:N]).count('1')
            if sub1 + sub3 > sub2 + sub3:
                result = max(result, sub1 + sub3 - sub1 * sub3)
    return result % (10**9 + 7)

