def subseq_mod():
    # Precompute combinations up to 10
    dp = [[0 for _ in range(11)] for _ in range(11)]
    dp[0][0] = 1

    for i in range(11):
        for j in range(i + 1):
            if j == 0:
                dp[i][j] = 1
            else:
                dp[i][j] = (dp[i - 1][j - 1] + dp[i - 1][j]) % MOD

    return dp

def count_interesting_subsets(n, slips):
    dp = subseq_mod()
    result = 0

    for i in range(len(slips)):
        for j in range(i + 1):
            taken = slips[i] >= j
            not_taken = dp[j][0] - dp[j - 1][0] if j > 0 else dp[j - 1][0]
            result += taken * not_taken
        if result >= MOD:
            result -= MOD

    return result % MOD

