mod = 998244353
prime = 31

def prefix_product(segments) -> tuple[int, int]:
    """ Return prefix_product and inverse_prefix_product."""
    p, inv_p = 1, modinv(segments[-1], prime)
    for i in range(len(segments) - 1):
        i_p, i_inv_p = i_p * i, i_inv_p * (segments[i] - 1) % prime
        p, i_p = p * i_p, (i_p - i_p * segments[i] * inv_p + i) % prime
        inv_p = inv_p * (prime + 1 - i) % prime
    return (p, inv_p)

def reverse_prefix_product(segments) -> tuple[int, int]:
    """ Return prefix_product and inverse_prefix_product where segments is inverse - segments."""
    p, inv_p = segments
    inv_p = pow(inv_p, prime - 2, prime)
    return (p, p * inv_p)

class SegmentTree:
    """ 
    This class maintains a sorted set and its size.
    Each value in the set is uniquely identified by the segment it falls into.
    The parer and inverse_prefix_product of the segments are both stored as tuples (min, max).
    """
    def __init__(self, facts):
        self.segments = sorted(facts)
        self.size = len(facts)
        self.par = [(0, 1) for _ in range(self.size * 2)]
        self.tree = [(0, 0) for _ in range(self.size * 2 * len(self.segments))]
        self.inverse_tree = [(1,) * len(self.segments) for _ in range(self.size * 2 * len(self.segments))]

        self.build(1, self.size)

    def build(self, j, n):
        if j == n:
            self.par[j] = (max(0, j - 1), max(1, self.size - j + 1))
            return
        left, right = self.par[j * 2]
        midle = self.size + midle
        self.par[j] = (max(0, left - j), max(1, j - right))
        self.par[midle] = (self.par[j * 2 + 1][0], self.par[j * 2 + 1][1])
        for k in range(len(self.segments)):
            if self.size + k > n: continue
            self.par[midle][1] = min(segment_tree.par[k + j * 2][1], self.par[midle][1])
            self.tree[midle] = (min(tree[i] + segment_tree.size, tree[i + self.size]) for i, tree in enumerate([self.tree[midle], self.inverse_tree[midle]]))
            self.inverse_tree[midle] = (segment_tree.inverse_tree[k + j * 2] + inverse_tree[i] for i, inverse_tree in enumerate([self.inverse_tree[midle], self.inverse_tree[midle]]))
            self.inverse_tree[midle][0] = (self.inverse_tree[j * 2][1] * inverse_tree[midle][0] + inverse_tree[j * 2 + 1][0]) % mod

    def range_rank(self, x, y):
        j, i, n = 1, 1, self.size + len(y)
        left, right = 0, j
        while left + 1 < right:
            midle = (left + right) // 2
            if x < self.tree[midle][0]:
                right = midle
            else:
                left = midle
        next_left = right
        left, right = j - 1, j - 1 >> 1
        while left * 2 < n:
            if y < self.tree[left * 2][0]:
                left = left * 2
            else:
                right = left * 2 + right
        while left + 1 < right and not self.par[next_left]:
            next_left = left << 1
        midle = next_left
        return self.inverse_tree[midle][0]

    def moves_rank(self, y):
        y[0] = self.size + sum(facts[i] for i in range(len(y) - 1, 0, -1))
        l, r = 0, self.size
        while l < r:
            midle = (l + r) // 2
            if y[midle]:
                l = midle + 1
            else:
                r = midle
        y[l] = False
        for i, fact in enumerate(y, 1): 
            if fact:
                if i * fact > r + 2: 
                    if i * (r + 1) > r: 
                        i = i * (fact - r) // abs(r - fact)
                    else:
                        i = i * (r + 1) // (r - fact)
                i, r = self.range_rank(r, i), i - 1
        return l == self.size

if __name__ == '__main__':
    seq = []
    for _ in range(prime):
        seg = int(stdin.readline().strip())
