    facts = SeqTree(itertools.product(seq, repeat=prime - 2))
    sequence = reversed(seq)
    ts = SegmentTree(facts)
    inv_ts = SegmentTree(facts[::-1])
    for i, seg in enumerate(sequence): 
        print(int(ts.moves_rank(seg) * inv_ts.moves_rank([0] + map(len, segment_tree.par, [seg])) % mod), sep='\n')
