from heapq import heappop, heappush

def find_min_money(N, M, start_vertices, transfer_edges, initial_money, A, B):
    graph = [[] for _ in range(N)]
    for u, v in transfer_edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    visited = [False] * N
    distances = [float('inf')] * N
    distance_queue = [i for i in range(N) if A[i] <= initial_money]

    def dijkstra(start):
        distances[start] = 0
        heapq.heapify(distance_queue)

        while distance_queue:
            current = heappop(distance_queue)
            if visited[current]:
                continue
            visited[current] = True
            for next_vertex in graph[current]:
                if distances[current] + transfer_edges[next_vertex][current] < distances[next_vertex]:
                    distances[next_vertex] = distances[current] + transfer_edges[next_vertex][current]
                    heappush(distance_queue, next_vertex)

    def dfs(start):
        visited=start
        dfs_stack = [start]
        while dfs_stack:
            current = dfs_stack.pop()
            if visited[current]:
                continue
            visited[current] = True
            for next_vertex in graph[current]:
                if A[next_vertex] <= initial_money:
                    dfs_stack.append(next_vertex)

    visited[start_vertices[0]] = True
    for s in start_vertices:
        dijkstra(s)

    visited = [False] * N
    visited[start_vertices[0]] = True
    for s in start_vertices:
        dfs(s)

    used = set()
    for start in start_vertices:
        for end in visited:
            used.add(start)
            used.add(end)
    for start in range(N):
        if start not in used:
            return float('inf')

    min_money = initial_money
    for s in start_vertices:
        dfs(s)
        if A[distance_queue[0]] <= initial_money:
            min_money = min(min_money, distance_queue[0])
        for start in start_vertices:
            dijkstra(start)
    return min_money

