def minCostToConnect(red_edges, blue_edges, red_positions, blue_positions):
    n = len(red_positions)
    blue_positions.sort()

    total_cost = 0
    red_edge_count = [0] * (n + 2)
    blue_edge_count = [0] * (n + 2)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    for i in range(1, n + 2):
        red_edge_count[i] = red_edges.count(red_positions + i)
        blue_edge_count[i] = blue_edges.count(blue_positions + i)

    def merge(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a != root_b:
            if red_edge_count[root_a] > red_edge_count[root_b]:
                root_a, root_b = root_b, root_a
            parent[root_b] = root_a

    parent = list(range(n + 2))
    red_total_cost = {}
    blue_total_cost = {}

    for i in range(1, n + 1):
        root_a = find(red_positions[i])
        root_b = find(blue_positions[i])
        if root_a != root_b:
            merge(root_a, root_b)
            cost = red_edge_count[root_a] * red_positions[i] + blue_edge_count[root_b] * blue_positions[i]
            cost = min(cost, cost - red_positions[i] + blue_positions[i])
            total_cost += cost
            if root_a in red_total_cost:
                red_total_cost[root_a] += cost - red_positions[i]
            else:
                red_total_cost[root_a] = cost - red_positions[i]
            if root_b in blue_total_cost:
                blue_total_cost[root_b] += cost - blue_positions[i]
            else:
                blue_total_cost[root_b] = cost - blue_positions[i]

    return total_cost + sum((red_total_cost[i] for i in red_positions)) + sum(blue_total_cost.values())

