def solve(initial_arrangement):
    n = len(initial_arrangement)
    # If the initial arrangement is all zeros, all boys will move left and girls will move right independently.
    if all(arrangement == 0 for arrangement in initial_arrangement):
        return n

    total_seconds = 0
    while not all(arrangement[total_seconds * n // 2:n] == 0 for arrangement in initial_arrangement):
        boys_idx = []
        for boy_position in range(n // 2, n):
            if initial_arrangement[boy_position] == 1:
                boys_idx.append(boy_position)

        for boy_name in boys_idx:
            for girl_name in range(boy_name + 1, n):
                if initial_arrangement[girl_name] == 0:
                    # Students swap positions with every second.
                    total_seconds += 1
                    initial_arrangement[boy_name], initial_arrangement[girl_name] = initial_arrangement[girl_name], initial_arrangement[boy_name]
                    break
        else:
            # If no matching girls are found to swap with boys every second, increment total seconds.
            for girl_name in range(n):
                if initial_arrangement[girl_name] == 0:
                    total_seconds += 1
                    break

    return total_seconds

