To solve this problem, we use a segment tree to efficiently handle the range queries and maximize the bitwise XOR. We first process the input, then build the segment tree and perform queries to find the maximum XOR for each test case. Finally, we print the result modulo 10^9 + 7.

```python
MOD = 10**9 + 7

def query(t, l, r, L, R, node):
    if L > R:
        return 0

    if l >= L and r <= R:
        return t[node]

    mid = (l + r) // 2
    res = 0
    if L <= mid:
        res = (res + query(t, l, mid, L, R, 2*node)) % MOD
    if R > mid:
        res = (res + query(t, mid + 1, r, L, R, 2*node + 1)) % MOD
    return res % MOD

def update(t, l, r, idx, node):
    if r <= idx or l >= idx:
        return

    if l == r:
        t[node] = idx
        return

    mid = (l + r) // 2
    update(t, l, mid, idx, 2*node)
    update(t, mid + 1, r, idx, 2*node + 1)
    t[node] = (t[2*node] | t[2*node+1]) % MOD

def maximumXOR(t, l, r, node):
    if l > r:
        return 0

    if l == r:
        return t[node]

    res = 0
    mid = (l + r) // 2
    res = (res * 2 + maximumXOR(t, l, mid, 2*node)) % MOD
    res = (res * 2 + maximumXOR(t, mid + 1, r, 2*node + 1)) % MOD
    return res % MOD

def solution():
    T = int(input())
    for _ in range(T):
        N = int(input())
        S = input()
        t = [0] * (4 * N)

        for i in range(N):
            if i % 2 == 0:
                t[i + N] = t[2 * i + 1] = S[i] ^ MOD
            else:
                t[2 * i] = t[i] = S[i]

        update(t, 0, 2 * N, 0)
        max_xor = 0

        for i in range(N):
            max_xor = (max_xor * 2 + maximumXOR(t, i, i + N // 2, 1)) % MOD
            max_xor = (max_xor * 2 + maximumXOR(t, i, i + 1 + N // 2, 1)) % MOD

        print(max_xor)
solution()
