from functools import lru_cache

def min_ones(n, m, mat):
    INF = (1 << 30) - 1
    @lru_cache(None)
    def dp(i, j):
        if i == n:
            return 0
        if j == m:
            return INF
        # Option 1: Invert row i
        inv_row_i = mat[i] ^ 1
        inc_1s = 0

        # Invert all values in column j
        for col in range(m):
            if mat[col][i] == '0':
                inv_col = '1'
            else:
                inv_col = '0'
            if mat[col][i] != inv_col:
                inc_1s += 1

        # The number of 1s in the new parity row
        row_newest = 0
        for col in range(m):
            if mat[col][i] != inv_col:
                row_newest += 1

        # Check with updated parities
        for col in range(m):
            if mat[col][i] != inv_col:
                if mat[col][j] == '0':
                    mat[col][j] = '1'
                else:
                    mat[col][j] = '0'
            if mat[col][i] == inv_col:
                if mat[col][j] == '0':
                    mat[col][j] = '0'
                else:
                    mat[col][j] = '1'

        # Option 2: Not invert row i
        row_original = dp(i + 1, j)
        # Option 3: Invert column j
        col_original = dp(i, j + 1)

        # Return the minimum number of 1s for this cell
        return min(invd_row_i[i] + inc_1s, row_newest + dp(i + 1, j), row_original + dp(i, j + 1) + col_original + 1) + 1
    return dp(0, 0).value

