import sys
import bisect

def find_min_cost(n, points):
    red_points = []
    blue_points = []

    for i, (pos, color) in enumerate(points):
        if color == 'R':
            red_points.append((pos, i))
        elif color == 'B':
            blue_points.append((pos, i))

    red_points.sort()

    total_cost = 0
    for i in range(len(red_points)):
        min_dist = sys.maxsize
        for j in range(len(red_points)):
            if j <= i:
                continue
            distance = red_points[j][0] - red_points[i][0]
            if distance < min_dist and distance != 0:
                min_dist = distance

        choice = sys.maxsize
        for j in range(len(blue_points)):
            distance = blue_points[j][0] - red_points[i][0]
            if distance < choice and distance != 0:
                choice = distance

        if choice == sys.maxsize:
            return -1

        red_points[i], blue_points[-1] = blue_points[-1], red_points[i]
        blue_points.pop()

        total_cost += min_dist + choice

    if len(red_points) == 0:
        return -1

    return total_cost

