def count_interesting_subsets(shoes):
    N = len(shoes)
    dp = [0] * (N + 1)
    dp[0] = 1  # Base case: empty subset is interesting

    for i in range(1, N + 1):
        pairs = []
        used = set()

        for j in range(i-1, 0, -1):
            if dp[j] == dp[i]:
                continue  # Already counted this subset
            if shoes[j] >= shoes[i]:
                if i < N:
                    pairs.append((shoes[j], shoes[i]))
                used.add(j)

        for p in pairs:
            if p == (shoes[i-1], shoes[i-1]):  # Avoid duplicates
                continue
            if p not in used:
                dp[i] = (dp[i] + dp[j]) % 998244353

        if i != N:
            dp[i] = (dp[i] + dp[i+1]) % 998244353

    return sum(dp) % 998244353

