from heapq import heappop, heappush
from collections import defaultdict

def dijkstra(graph, start, end):
    distances = {city: float('inf') for city in graph}
    distances[start] = 0
    queue = [(-1, start)]
    while queue:
        (_, current_city) = heappop(queue)
        if current_city == end:
            break
        for neighbor, weight in graph[current_city]:
            if distances[neighbor] > distances[current_city] + weight:
                distances[neighbor] = distances[current_city] + weight
                heappush(queue, (-distances[neighbor], neighbor))
    return distances[end]

def can_tavas_win(winner, distances, num_pickups):
    if max(winner) == num_pickups:
        return True
    if sum(winner) == 0:
        return True
    return False

