    for i in range(1, n + 1):
        distance = max(distance, dijkstra(graph, tic + 1, i))

    if distance > tic:
        return "Break a heart"
    if distance == tic and sum(pi) == 0:
        return "Break a heart"
    if distance == tic and sum(pi) > 0:
        return "Cry"
    return "Flowers"

print(solution(4, 4, 1, 2, [3, 2, 5, -11]))
print(solution(5, 4, 1, 2, [2, 2, -5, -4, 6]))
print(solution(2, 1, 1, 2, [-5, -5]))
```

