from collections import deque

def findEdgeCost(n, points):
    queue = deque(points)
    red_y, green_y = -1, -1
    blue_y = -1
    cost_y = float('inf')

    while queue:
        p, c = queue.popleft()

        if c == 'R':
            if red_y == -1:
                red_y = p
            else:
                green_y = p
        elif c == 'G':
            if green_y == -1:
                green_y = p
            else:
                blue_y = p
        else:
            if blue_y == -1:
                blue_y = p
            else:
                red_y = p

        if (min(green_y, blue_y) < min(red_y, green_y) and green_y >= min(red_y, green_y) or
                min(blue_y, red_y) < min(green_y, blue_y) and blue_y >= min(green_y, blue_y) or
                (green_y == -1 and red_y < green_y - n or 
                 blue_y == -1 and red_y < blue_y - n)
               ):
            return -1

        if queue:
            cost = sum(p-q for _,c,_ in sorted(queue, key=lambda x: x[0])) - cost_y
            if cost < cost_y:
                cost_y = cost

    return cost_y

# Example usage
n = int(input())
points = [tuple(map(int, input().split())) for _ in range(n)]
print(findEdgeCost(n, points))
```

